import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

// Cap how many ids we keep so the persisted store cannot grow without bound. Once a
// deletion has propagated the backend stops returning the recording, so old ids are safe
// to forget — we only need the recent ones to hide rows during that propagation window.
const MAX_TRACKED_DELETED_IDS = 1000

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface deletedRecordingsLogicValues {
    deletedRecordingIdList: string[]
    deletedRecordingIds: Set<string>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface deletedRecordingsLogicActions {
    addDeletedRecordings: (ids: string[]) => {
        ids: string[]
    }
}

export type deletedRecordingsLogicType = MakeLogicType<deletedRecordingsLogicValues, deletedRecordingsLogicActions>

export const deletedRecordingsLogic = kea<deletedRecordingsLogicType>([
    path(['scenes', 'session-recordings', 'deletedRecordingsLogic']),
    actions({
        addDeletedRecordings: (ids: string[]) => ({ ids }),
    }),
    reducers({
        // Persisted as an array because localStorage serialization is JSON, which cannot round-trip a Set.
        deletedRecordingIdList: [
            [] as string[],
            { persist: true },
            {
                addDeletedRecordings: (state, { ids }) => {
                    const next = state.filter((id) => !ids.includes(id))
                    next.push(...ids)
                    return next.slice(-MAX_TRACKED_DELETED_IDS)
                },
            },
        ],
    }),
    selectors({
        deletedRecordingIds: [
            (s) => [s.deletedRecordingIdList],
            (deletedRecordingIdList: string[]): Set<string> => new Set(deletedRecordingIdList),
        ],
    }),
])
